export const financeEntries=sqliteTable("finance_entries",{id:text("id").primaryKey(),accountId:text("account_id").notNull(),amountCents:integer("amount_cents").notNull(),category:text("category").notNull(),costCenter:text("cost_center"),description:text("description").notNull(),referenceType:text("reference_type"),referenceId:text("reference_id"),status:text("status").notNull().default("posted"),reversalOf:text("reversal_of"),createdBy:text("created_by").notNull(),bookedAt:text("booked_at").notNull().default(sql`CURRENT_TIMESTAMP`)},t=>[index("idx_finance_entries_account_time").on(t.accountId,t.bookedAt)]);
export const budgets=sqliteTable("budgets",{id:text("id").primaryKey(),vtcId:text("vtc_id").notNull(),name:text("name").notNull(),costCenter:text("cost_center").notNull(),period:text("period").notNull(),limitCents:integer("limit_cents").notNull(),spentCents:integer("spent_cents").notNull().default(0),active:integer("active",{mode:"boolean"}).notNull().default(true)},t=>[uniqueIndex("idx_budgets_vtc_center_period").on(t.vtcId,t.costCenter,t.period)]);
export const careerProfiles=sqliteTable("career_profiles",{id:text("id").primaryKey(),vtcId:text("vtc_id").notNull(),userId:text("user_id").notNull(),xp:integer("xp").notNull().default(0),level:integer("level").notNull().default(1),safetyScore:real("safety_score").notNull().default(100),efficiencyScore:real("efficiency_score").notNull().default(100),reliabilityScore:real("reliability_score").notNull().default(100),streakDays:integer("streak_days").notNull().default(0),updatedAt:text("updated_at").notNull().default(sql`CURRENT_TIMESTAMP`)},t=>[uniqueIndex("idx_career_vtc_user").on(t.vtcId,t.userId),index("idx_career_vtc_xp").on(t.vtcId,t.xp)]);
