export const challenges=sqliteTable("challenges",{id:text("id").primaryKey(),vtcId:text("vtc_id"),name:text("name").notNull(),description:text("description"),metric:text("metric").notNull(),target:real("target").notNull(),startsAt:text("starts_at").notNull(),endsAt:text("ends_at").notNull(),xpReward:integer("xp_reward").notNull().default(0),active:integer("active",{mode:"boolean"}).notNull().default(true),createdBy:text("created_by").notNull()},t=>[index("idx_challenges_active").on(t.vtcId,t.active,t.endsAt)]);
export const challengeProgress=sqliteTable("challenge_progress",{id:text("id").primaryKey(),challengeId:text("challenge_id").notNull(),userId:text("user_id").notNull(),value:real("value").notNull().default(0),completedAt:text("completed_at"),rewardedAt:text("rewarded_at"),updatedAt:text("updated_at").notNull().default(sql`CURRENT_TIMESTAMP`)},t=>[uniqueIndex("idx_challenge_user").on(t.challengeId,t.userId)]);
export const discordGuilds=sqliteTable("discord_guilds",{guildId:text("guild_id").primaryKey(),vtcId:text("vtc_id"),welcomeChannelId:text("welcome_channel_id"),welcomeMessage:text("welcome_message").notNull().default("Willkommen {user} bei {vtc}!") ,announcementChannelId:text("announcement_channel_id"),ticketCategoryId:text("ticket_category_id"),supportRoleId:text("support_role_id"),autoRoleIds:text("auto_role_ids").notNull().default("[]"),enabled:integer("enabled",{mode:"boolean"}).notNull().default(true),updatedBy:text("updated_by"),updatedAt:text("updated_at").notNull().default(sql`CURRENT_TIMESTAMP`)});
