export const ticketMessages=sqliteTable("ticket_messages",{id:text("id").primaryKey(),ticketId:text("ticket_id").notNull(),authorId:text("author_id"),authorType:text("author_type").notNull(),body:text("body").notNull(),internal:integer("internal",{mode:"boolean"}).notNull().default(false),createdAt:text("created_at").notNull().default(sql`CURRENT_TIMESTAMP`)},t=>[index("idx_ticket_messages_ticket_time").on(t.ticketId,t.createdAt)]);
